import Foundation
import Testing
@testable import UsageMeterCore

func makeTestJWT(payload: [String: Any]) throws -> String {
    let header = try JSONSerialization.data(
        withJSONObject: ["alg": "none"]
    )
    let payload = try JSONSerialization.data(withJSONObject: payload)
    return [
        header.base64URLEncodedString(),
        payload.base64URLEncodedString(),
        "signature"
    ].joined(separator: ".")
}

func oauthFormValues(from request: URLRequest) throws -> [String: String] {
    let data = try #require(request.httpBody)
    let body = try #require(String(data: data, encoding: .utf8))
    var components = URLComponents()
    components.percentEncodedQuery = body
    return Dictionary(
        uniqueKeysWithValues: (components.queryItems ?? []).compactMap {
            item in item.value.map { (item.name, $0) }
        }
    )
}

import Foundation
import Testing
@testable import UsageMeterCore

@Suite
struct OAuthCallbackParserTests {
    @Test
    func returnsAuthorizationCodeForMatchingCallback() throws {
        let url = try #require(
            URL(string: "http://127.0.0.1:1455/auth/callback?code=authorization-code&state=expected-state")
        )

        let code = try OAuthCallbackParser.parse(
            url: url,
            expectedState: "expected-state"
        )

        #expect(code == "authorization-code")
    }

    @Test
    func rejectsCallbackForAnotherPath() throws {
        let url = try #require(
            URL(string: "http://127.0.0.1:1455/not-the-callback?code=secret-code&state=expected-state")
        )

        #expect(throws: OAuthCallbackError.invalidPath) {
            try OAuthCallbackParser.parse(
                url: url,
                expectedState: "expected-state"
            )
        }
    }

    @Test
    func rejectsCallbackWithWrongOrMissingState() throws {
        let wrongStateURL = try #require(
            URL(string: "http://127.0.0.1:1455/auth/callback?code=secret-code&state=wrong-state")
        )
        let missingStateURL = try #require(
            URL(string: "http://127.0.0.1:1455/auth/callback?code=secret-code")
        )

        #expect(throws: OAuthCallbackError.stateMismatch) {
            try OAuthCallbackParser.parse(
                url: wrongStateURL,
                expectedState: "expected-state"
            )
        }
        #expect(throws: OAuthCallbackError.stateMismatch) {
            try OAuthCallbackParser.parse(
                url: missingStateURL,
                expectedState: "expected-state"
            )
        }
    }

    @Test
    func rejectsCallbackWithMissingOrEmptyCode() throws {
        let missingCodeURL = try #require(
            URL(string: "http://127.0.0.1:1455/auth/callback?state=expected-state")
        )
        let emptyCodeURL = try #require(
            URL(string: "http://127.0.0.1:1455/auth/callback?code=&state=expected-state")
        )

        #expect(throws: OAuthCallbackError.missingCode) {
            try OAuthCallbackParser.parse(
                url: missingCodeURL,
                expectedState: "expected-state"
            )
        }
        #expect(throws: OAuthCallbackError.missingCode) {
            try OAuthCallbackParser.parse(
                url: emptyCodeURL,
                expectedState: "expected-state"
            )
        }
    }

    @Test
    func errorDescriptionsDoNotIncludeCallbackSecrets() throws {
        let state = "private-state-value"
        let code = "private-authorization-code"
        let url = try #require(
            URL(string: "http://127.0.0.1:1455/wrong?code=\(code)&state=\(state)")
        )

        do {
            _ = try OAuthCallbackParser.parse(url: url, expectedState: state)
            Issue.record("Expected callback parsing to fail")
        } catch {
            let description = String(describing: error)
            #expect(!description.contains(state))
            #expect(!description.contains(code))
        }
    }
}

import Foundation
import Testing

@testable import UsageMeterCore

@Suite
struct SuperGrokAuthDocumentDecoderTests {
    @Test
    func oidcCredentialIsPreferredAndKeepsStableIdentity() throws {
        let data = Data(
            """
            {
              "https://accounts.x.ai/sign-in": {
                "key": "legacy-token",
                "email": "legacy@example.com"
              },
              "https://auth.x.ai::profile": {
                "key": "oidc-token",
                "email": "User@Example.COM",
                "team_id": "team-1",
                "user_id": "user-1",
                "auth_mode": "oidc",
                "create_time": "2026-08-01T11:00:00Z",
                "expires_at": "2026-08-01T12:00:00Z",
                "refresh_token": "refresh-token",
                "oidc_issuer": "https://auth.x.ai",
                "oidc_client_id": "client-1"
              }
            }
            """.utf8
        )

        let credential = try SuperGrokAuthDocumentDecoder()
            .decode(data)

        #expect(credential.accessToken == "oidc-token")
        #expect(credential.email == "User@Example.COM")
        #expect(credential.teamID == "team-1")
        #expect(credential.userID == "user-1")
        #expect(credential.authMode == "oidc")
        #expect(credential.refreshToken == "refresh-token")
        #expect(credential.oidcIssuer == "https://auth.x.ai")
        #expect(credential.oidcClientID == "client-1")
        #expect(
            credential.createdAt
                == Date(
                    timeIntervalSince1970: 1_785_582_000
                )
        )
        #expect(credential.identityKey == "user-1::team-1")
        #expect(
            credential.expiresAt
                == Date(
                    timeIntervalSince1970: 1_785_585_600
                )
        )
    }

    @Test
    func existingCredentialJSONRemainsReadable() throws {
        let credential = try JSONDecoder().decode(
            SuperGrokCredential.self,
            from: Data(
                #"""
                {
                  "accessToken": "existing-token",
                  "email": "user@example.com",
                  "teamID": "team-1",
                  "userID": "user-1",
                  "authMode": "oidc",
                  "expiresAt": null
                }
                """#.utf8
            )
        )

        #expect(credential.accessToken == "existing-token")
        #expect(credential.refreshToken == nil)
        #expect(credential.oidcIssuer == nil)
        #expect(credential.oidcClientID == nil)
        #expect(credential.createdAt == nil)
    }

    @Test
    func credentialWithoutBillingUserIDIsRejected() throws {
        let data = Data(
            """
            {
              "key": "direct-token",
              "email": "User@Example.COM"
            }
            """.utf8
        )

        #expect(
            throws:
                ProviderClientError
                .unsupportedResponse
        ) {
            _ = try SuperGrokAuthDocumentDecoder()
                .decode(data)
        }
    }

    @Test
    func missingAccessTokenIsRejected() {
        let data = Data(
            """
            {
              "https://auth.x.ai::profile": {
                "email": "user@example.com"
              }
            }
            """.utf8
        )

        #expect(
            throws:
                ProviderClientError
                .reauthenticationRequired
        ) {
            _ = try SuperGrokAuthDocumentDecoder()
                .decode(data)
        }
    }
}

