        osVersion: "Version 26.5",
        id: "device-123",
        clientVersion: "1.45.0"
    )

    @Test
    func deviceAuthorizationUsesCurrentKimiContract() throws {
        let request = try KimiOAuthRequests.deviceAuthorizationRequest(
            device: device
        )
        let form = try oauthFormValues(from: request)

        #expect(
            request.url?.absoluteString
                == "https://auth.kimi.com/api/oauth/device_authorization"
        )
        #expect(request.httpMethod == "POST")
        #expect(form == ["client_id": KimiOAuthRequests.clientID])
        expectDeviceHeaders(on: request)
    }

    @Test
    func deviceTokenPollUsesRFC8628Grant() throws {
        let request = try KimiOAuthRequests.deviceTokenRequest(
            deviceCode: "device-code",
            device: device
        )
        let form = try oauthFormValues(from: request)

        #expect(
            request.url?.absoluteString
                == "https://auth.kimi.com/api/oauth/token"
        )
        #expect(form["client_id"] == KimiOAuthRequests.clientID)
        #expect(form["device_code"] == "device-code")
        #expect(
            form["grant_type"]
                == "urn:ietf:params:oauth:grant-type:device_code"
        )
        expectDeviceHeaders(on: request)
    }

    @Test
    func refreshUsesKimiOAuthGrant() throws {
        let request = try KimiOAuthRequests.refreshRequest(
            refreshToken: "refresh-token",
            device: device
        )
        let form = try oauthFormValues(from: request)

        #expect(form["client_id"] == KimiOAuthRequests.clientID)
        #expect(form["grant_type"] == "refresh_token")
        #expect(form["refresh_token"] == "refresh-token")
        expectDeviceHeaders(on: request)
    }

    private func expectDeviceHeaders(on request: URLRequest) {
        #expect(
            request.value(forHTTPHeaderField: "Content-Type")
                == "application/x-www-form-urlencoded"
        )
        #expect(
            request.value(forHTTPHeaderField: "X-Msh-Platform")
                == "kimi_cli"
        )
        #expect(
            request.value(forHTTPHeaderField: "X-Msh-Version")
                == device.clientVersion
        )
        #expect(
            request.value(forHTTPHeaderField: "X-Msh-Device-Name")
                == device.name
        )
        #expect(
            request.value(forHTTPHeaderField: "X-Msh-Device-Model")
                == device.model
        )
        #expect(
            request.value(forHTTPHeaderField: "X-Msh-Os-Version")
                == device.osVersion
        )
        #expect(
            request.value(forHTTPHeaderField: "X-Msh-Device-Id")
                == device.id
        )
    }
}

import Foundation
import Testing

@testable import UsageMeterCore

@Suite
struct SuperGrokDeviceAuthenticationFlowTests {
    @Test
    func processRunnerStreamsCommandOutput()
        async throws
    {
        let output = OutputRecorder()
        let status = try await CLIProcessRunner()
            .run(
                CLIProcessInvocation(
                    executableURL: URL(
                        fileURLWithPath:
                            "/bin/echo"
                    ),
                    arguments: ["device-ready"],
                    environment:
                        ProcessInfo.processInfo
                        .environment
                )
            ) { chunk in
                await output.append(chunk)
            }

        #expect(status == 0)
        #expect(
            await output.value
                == "device-ready\n"
        )
    }

    @Test
    func deviceAuthenticationUsesOnlyTheAttemptProfile()
        async throws
    {
        let profileDirectory =
            FileManager.default.temporaryDirectory
            .appending(
                path:
                    "supergrok-flow-\(UUID().uuidString)"
            )
        defer {
            try? FileManager.default.removeItem(
                at: profileDirectory
            )
        }
        let invocationRecorder =
            InvocationRecorder()
        let promptRecorder = PromptRecorder()
        let flow =
            SuperGrokDeviceAuthenticationFlow(
                executableURL: URL(
                    fileURLWithPath:
                        "/usr/bin/true"
                ),
                profileDirectory:
                    profileDirectory,
                baseEnvironment: [
                    "PATH": "/usr/local/bin:/usr/bin",
                    "GROK_HOME": "/Users/test/.grok",
                    "GROK_AUTH_FILE":
                        "/Users/test/default.json",
                    "GROK_ACCESS_TOKEN":
                        "default-token",
                    "XAI_API_KEY": "default-api-key",
                ],
                run: {
                    invocation,
                    onOutput in
                    await invocationRecorder.record(
                        invocation
                    )
                    try FileManager.default
                        .createDirectory(
                            at: profileDirectory,
                            withIntermediateDirectories:
                                true
                        )
                    try Data(
                        """
                        {
                          "https://auth.x.ai::profile": {
                            "key": "isolated-token",
                            "email": "user@example.com",
                            "user_id": "user-1",
                            "team_id": "team-1",
                            "auth_mode": "oidc"
                          }
                        }
                        """.utf8
                    ).write(
                        to:
                            profileDirectory
                            .appending(
                                path: "auth.json"
                            )
                    )
                    await onOutput(
                        """
                        To sign in, open this URL in your browser:
                          https://auth.x.ai/device
                        Confirm this code in your browser:
                          ABCD-EFGH
                        """
                    )
                    return 0
                }
            )

        let credential =
            try await flow
            .authenticate { prompt in
                await promptRecorder.record(
                    prompt
                )
            }

        #expect(
            credential.accessToken
                == "isolated-token"
        )
        let invocation = try #require(
            await invocationRecorder.invocation
        )
        #expect(
            invocation.executableURL.path
                == "/usr/bin/true"
        )
        #expect(
            invocation.arguments
                == ["login", "--device-auth"]
        )
        #expect(
            invocation.environment["GROK_HOME"]
                == profileDirectory.path
        )
        #expect(
            invocation.environment["PATH"]
                == "/usr/local/bin:/usr/bin"
        )
        #expect(
            invocation.environment[
                "GROK_AUTH_FILE"
            ] == nil
        )
        #expect(
