  let reset = Date(timeIntervalSince1970: 2_000_000_000)
  let window = try #require(
    UsageWindow(
      id: "five-hour",
      kind: .short,
      duration: 18000,
      resetAt: reset,
      consumedFraction: 0.81
    )
  )

  #expect(window.startAt == reset.addingTimeInterval(-18000))
  #expect(abs(window.remainingFraction - 0.19) < 0.000_001)
}

@Test
