  let reset = Date(timeIntervalSince1970: 2_000_000_000)

  #expect(
    UsageWindow(
      id: "zero-duration",
      kind: .short,
      duration: 0,
      resetAt: reset,
      consumedFraction: 0.5
    ) == nil
  )
  #expect(
    UsageWindow(
      id: "over-consumed",
      kind: .weekly,
      duration: 604_800,
      resetAt: reset,
      consumedFraction: 1.1
    ) == nil
  )
  #expect(
    UsageWindow(
      id: "not-finite",
      kind: .weekly,
      duration: 604_800,
      resetAt: reset,
      consumedFraction: .infinity
    ) == nil
  )
}

@Test
